"""Shared-collection retrieval for a multi-tenant support agent.

The tenant boundary is structural, not a habit: every search goes through a
scoped handle that cannot be constructed without a tenant, the filter is built
by enforce_tenant rather than by each call site, and the tenant also selects a
dedicated shard so a filter bug cannot reach another tenant is data.
"""

from qdrant_client import QdrantClient, models

client = QdrantClient(url="http://vectors.internal:6333")
COLLECTION = "documents"


def enforce_tenant(tenant_id):
    if not tenant_id:
        raise ValueError("unscoped retrieval is forbidden: tenant_id is required")
    return models.Filter(
        must=[
            models.FieldCondition(
                key="tenant_id",
                match=models.MatchValue(value=tenant_id),
            )
        ]
    )


class TenantScopedIndex:
    """A handle that cannot exist without a tenant."""

    def __init__(self, tenant_id):
        if not tenant_id:
            raise ValueError("unscoped retrieval is forbidden: tenant_id is required")
        self.tenant_id = tenant_id

    def search(self, query_vector, limit=8):
        return client.search(
            collection_name=COLLECTION,
            query_vector=query_vector,
            query_filter=enforce_tenant(self.tenant_id),
            shard_key_selector=self.tenant_id,
            limit=limit,
        )


def answer(question, embed, tenant_id):
    hits = TenantScopedIndex(tenant_id).search(embed(question), limit=8)
    return "\n".join(h.payload["text"] for h in hits)


def summarise_recent(embed, tenant_id):
    hits = TenantScopedIndex(tenant_id).search(embed("recent escalations"), limit=20)
    return [h.payload["text"] for h in hits]
